import 'package:flutter/material.dart';import 'package:sizer/sizer.dart';import 'package:smart_coach_new/core/utils/color_constants.dart';class CustomButton extends StatelessWidget {  final String text;  final Color? color;  final Color textColor;  final VoidCallback? onPressed;  final IconData? sufixIcon;  final IconData? prefixIcon;  final EdgeInsetsGeometry? padding;  final double radius;  final double textSize;  final double iconSize;  final bool showBorder;  final Color? borderColor;  final bool isDisabled;  const CustomButton(      {super.key,        required this.text,        this.color = ColorConstants.primary,        this.textColor = Colors.white,        this.onPressed,        this.sufixIcon,        this.prefixIcon,        this.padding,        this.radius = 10,        this.textSize = 13,        this.iconSize = 3.5,        this.showBorder = false,        this.borderColor,        this.isDisabled = false});  @override  Widget build(BuildContext context) {    return GestureDetector(      onTap: onPressed,      child: Container(        padding: padding ?? EdgeInsets.symmetric(vertical: 1.8.h, horizontal: 6.w),        decoration: BoxDecoration(          color: isDisabled ? ColorConstants.disabledButtonBgColor : color,          borderRadius: BorderRadius.circular(radius),          border: showBorder ? Border.all(color: borderColor ?? Colors.grey.shade300) : null,        ),        alignment: Alignment.center,        child: Row(          mainAxisAlignment: MainAxisAlignment.center,          crossAxisAlignment: CrossAxisAlignment.center,          mainAxisSize: MainAxisSize.min,          children: [            if (prefixIcon != null)              Container(                margin: EdgeInsets.only(right: 1.w),                child: Icon(                  prefixIcon,                  size: iconSize.w,                  color: textColor,                ),              ),            Text(              text,              textAlign: TextAlign.center,              style: TextStyle(                color: isDisabled ? ColorConstants.disabledButtonTextColor : textColor,                fontSize: textSize.sp,                fontWeight: FontWeight.w500,                height: 1,              ),            ),            if (sufixIcon != null)              Container(                margin: EdgeInsets.only(left: 1.w),                child: Icon(                  sufixIcon,                  size: iconSize.w,                  color: textColor,                ),              ),          ],        ),      ),    );  }}